UPDATE file_jobs
SET status = 'SUCCEEDED',
    lease_until = NULL,
    dispatch_after = NULL,
    dispatch_token = NULL,
    failure_code = NULL,
    failure_message = NULL,
    finished_at = #{now},
    updated_at = #{now}
WHERE id = #{jobId}
    AND status = 'RUNNING'
    AND attempt_count = #{expectedAttemptCount}
    AND lease_until > #{now}

UPDATE file_jobs
SET status = 'FAILED',
    lease_until = NULL,
    dispatch_after = NULL,
    dispatch_token = NULL,
    failure_code = #{failureCode},
    failure_message = #{failureMessage},
    finished_at = #{now},
    updated_at = #{now}
WHERE id = #{jobId}
    AND status = 'RUNNING'
    AND attempt_count = #{expectedAttemptCount}
    AND lease_until > #{now}
